#!/usr/bin/env node
// jp-西日本旅客鉄道-越美北線 display: display intervals 1,7,8,9,10,12,16 and aliases 002762,002759,002763 refitted onto the Apple glyph; physical source unchanged.
// Generated by repair-05 (railway-evidence/local/proposals/repair-05-kit-20261021/mkrepair.mjs) from the Yokogawara v5 pattern.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {fileURLToPath} from 'node:url';
import {partRowsForLine} from './build-display-lanes.mjs';
import {assertAllowedCandidateFile} from './local-evidence-path.mjs';
import {refreshDependencyReferences, applyPreparedWrites, DEPENDENCY_PATHS} from './repair-three-reversal-extents.mjs';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const APP = path.join(REPO, 'app'), EV = path.join(REPO, 'railway-evidence/local');
export const AUTHORITY_PATH = path.join(EV, 'proposals/jr-west-etsumihoku-20261021/authority-display-v1.json');
const LINE = 'jp-西日本旅客鉄道-越美北線', KEY = 'jr-west-etsumihoku-display', FORMAT = 'jtm-jr-west-etsumihoku-display-authority-v1', REVIEW_FORMAT = 'jtm-jr-west-etsumihoku-display-candidate-review-v1';
const STATIONS = ["002762","002759","002763"], INTERVALS = [1,7,8,9,10,12,13,16,17];
const DISPLAY_INTERVALS = [1,7,8,9,10,12,16];
const BASELINE_SHA = '00c18d42017789011a512d8506b5d97f12ea974f6918726e30680c29b2ffeec8';
const CANDIDATE_SHA = '6dc3f5b03c1c40981a1627cf275347bce4f59adf20b8b6e14bd6a8e6fadd78b9';
const NATIVE_SHA = '6005ca54937f84e117cdb68a6779e53c01a10fb829eae5fcd5ab665de3dde93a';
const PART_COUNTS = [959], BASE_PART_COUNTS = [694];
const PREFIX = 49, SUFFIX = 87;
const net = createRequire(import.meta.url)('../../public/rail-network.js');
const read = p => JSON.parse(fs.readFileSync(p));
const equal = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const sha = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');

function proposedLine(e) {
  assert.deepEqual([e.format, e.lineID, e.stationIDs, e.intervalIndices, e.displayOverrideIntervals,
    e.nativePointCount, e.MainCertified, e.wholeLineAccepted],
  [FORMAT, LINE, STATIONS, INTERVALS, DISPLAY_INTERVALS, PART_COUNTS.reduce((a, b) => a + b, 0), false, false],
  KEY + ' authority scope changed');
  assert.equal(sha(e.baselineLine), BASELINE_SHA, KEY + ' baseline authority changed');
  assert.equal(sha(e.candidateLine), CANDIDATE_SHA, KEY + ' candidate authority changed');
  assert.equal(sha(e.baselineNativeRows), NATIVE_SHA, KEY + ' baseline native authority changed');
  const before = e.baselineLine, after = e.candidateLine;
  const reconstructed = structuredClone(before);
  reconstructed.displayIntervalCoordinates ??= {};
  for (const i of DISPLAY_INTERVALS) reconstructed.displayIntervalCoordinates[i] = structuredClone(after.displayIntervalCoordinates[i]);
  if (STATIONS.length) {
    reconstructed.displayStationCoordinates ??= {};
    for (const id of STATIONS) reconstructed.displayStationCoordinates[id] = structuredClone(after.displayStationCoordinates[id]);
  }
  assert.deepEqual(reconstructed, after, 'Only the listed display intervals and aliases may change');
  for (const [id, c] of Object.entries(before.displayStationCoordinates || {}))
    assert.deepEqual(after.displayStationCoordinates[id], c, 'Preserved aliases changed');
  const physical = l => Object.fromEntries(Object.entries(l).filter(([k]) => k !== 'displayIntervalCoordinates' && k !== 'displayStationCoordinates'));
  assert.deepEqual(physical(after), physical(before), KEY + ' non-display fields changed');
  assert.deepEqual(net.decodeIntervals(after), net.decodeIntervals(before), 'Physical source changed');
  for (const [k, v] of Object.entries(before.displayIntervalCoordinates || {})) if (!DISPLAY_INTERVALS.includes(+k))
    assert.deepEqual(after.displayIntervalCoordinates[k], v);
  const oldParts = net.displayPartsForLine(before), parts = net.displayPartsForLine(after);
  assert.deepEqual(oldParts.map(p => p.length), BASE_PART_COUNTS);
  assert.deepEqual(parts.map(p => p.length), PART_COUNTS);
  assert.deepEqual(parts[0].slice(0, PREFIX), oldParts[0].slice(0, PREFIX), 'Outer public prefix changed');
  if (SUFFIX) assert.deepEqual(parts.at(-1).slice(-SUFFIX), oldParts.at(-1).slice(-SUFFIX), 'Outer public suffix changed');
  return structuredClone(after);
}

export function repairPackage(input, e = read(AUTHORITY_PATH)) {
  const line = proposedLine(e), own = input.lines.filter(l => l.id === LINE);
  assert.equal(own.length, 1, KEY + ' own line missing/duplicated');
  assert(equal(own[0], e.baselineLine) || equal(own[0], line), KEY + ' stale own package baseline');
  const result = structuredClone(input);
  result.lines = result.lines.map(l => l.id === LINE ? line : l);
  const provenance = {lineID: LINE, stationIDs: STATIONS, intervalIndices: INTERVALS,
    evidence: path.relative(REPO, AUTHORITY_PATH), physicalTopologyChanged: false,
    status: 'bounded-jr-west-etsumihoku-display; full-passenger-caps-open', wholeLineAccepted: false, MainCertified: false};
  result.geometrySource ??= {}; result.geometrySource.manualOverrides ??= {};
  const previous = result.geometrySource.manualOverrides[KEY];
  assert(previous === undefined || equal(previous, provenance), KEY + ' provenance changed');
  result.geometrySource.manualOverrides[KEY] = provenance;
  return result;
}

export function repairParts(pkg, input, e = read(AUTHORITY_PATH)) {
  const ownLines = pkg.lines.filter(l => l.id === LINE);
  assert.equal(ownLines.length, 1, KEY + ' candidate line missing/duplicated');
  const line = ownLines[0]; assert.deepEqual(line, proposedLine(e));
  const parts = net.displayPartsForLine(line), rows = partRowsForLine(line, parts, null, null);
  assert.equal(rows.length, parts.length);
  rows.forEach((r, i) => { assert.equal(r[4], PART_COUNTS[i]); assert.deepEqual(r[7], parts[i]); });
  const own = input.partsByRegion?.jp?.filter(r => r[0] === LINE);
  assert.equal(own?.length, BASE_PART_COUNTS.length, KEY + ' own native rows missing/duplicated');
  assert(equal(own, e.baselineNativeRows) || equal(own, rows), KEY + ' stale/foreign own native row');
  // colorByRegion / renderGroupByRegion carry colour and render-group identity derived from the line's
  // colour and name, not its geometry: allowed, carried over unchanged, and checked against the line.
  const IDENTITY_KEYS = ['colorByRegion', 'renderGroupByRegion'];
  for (const [key, value] of Object.entries(input)) if (key !== 'partsByRegion' && !IDENTITY_KEYS.includes(key))
    assert(!JSON.stringify(value)?.includes(LINE), KEY + ' own native reference requires review: ' + key);
  for (const key of IDENTITY_KEYS) for (const [region, values] of Object.entries(input[key] || {}))
    if (values && Object.hasOwn(values, LINE)) {
      assert.equal(region, 'jp', KEY + ' foreign-region identity reference: ' + key);
      if (key === 'colorByRegion') assert.equal(values[LINE].color, line.color, KEY + ' colour identity changed');
    }
  for (const [region, values] of Object.entries(input.partsByRegion || {})) if (region !== 'jp')
    assert(!JSON.stringify(values).includes(LINE), KEY + ' foreign-region own reference');
  assert(!(input.excludedOperators || []).includes(line.operator), KEY + ' operator excluded');
  const result = structuredClone(input), jp = result.partsByRegion.jp;
  const first = jp.findIndex(r => r[0] === LINE);
  result.partsByRegion.jp = [...jp.slice(0, first).filter(r => r[0] !== LINE), ...rows, ...jp.slice(first).filter(r => r[0] !== LINE)];
  return result;
}

export function validateCandidateReview(receipt, line) {
  assert(receipt, KEY + ' scoped candidate-review receipt required before --apply');
  assert.deepEqual([receipt.format, receipt.status, receipt.lineID, receipt.stationIDs,
    receipt.intervalIndices, receipt.MainCertified, receipt.wholeLineAccepted],
  [REVIEW_FORMAT, 'bounded-candidate-reviewed', LINE, STATIONS, INTERVALS, false, false], KEY + ' review scope changed');
  assert.equal(receipt.reviewedOwnLineSha256, CANDIDATE_SHA, KEY + ' reviewed candidate changed');
  assert.equal(receipt.reviewedOwnLineSha256, sha(line), KEY + ' reviewed own line changed');
}

function main(args) {
  assert(args.length === 3 && args[0] === '--apply' && args[1] === '--candidate-review',
    'Use --apply --candidate-review <canonical evidence receipt.json>');
  const receiptPath = path.resolve(args[2]); assertAllowedCandidateFile(receiptPath);
  assert(fs.realpathSync(receiptPath).startsWith(fs.realpathSync(EV) + path.sep),
    KEY + ' receipt must use canonical local evidence');
  const snapshot = p => ({path: p, before: fs.readFileSync(p)});
  const authority = snapshot(AUTHORITY_PATH), receipt = snapshot(receiptPath), e = JSON.parse(authority.before);
  const paths = {package: 'public/rail/jp-2025.json', lanes: 'public/rail/display-lanes.json', ...DEPENDENCY_PATHS};
  const inputs = Object.fromEntries(Object.entries(paths).map(([k, p]) => [k, snapshot(path.join(APP, p))]));
  const load = k => JSON.parse(inputs[k].before), pkg = repairPackage(load('package'), e);
  validateCandidateReview(JSON.parse(receipt.before), pkg.lines.find(l => l.id === LINE));
  const lanes = repairParts(pkg, load('lanes'), e);
  const dependencies = refreshDependencyReferences(pkg,
    Object.fromEntries(Object.keys(DEPENDENCY_PATHS).map(k => [k, load(k)])));
  const outputs = {package: JSON.stringify(pkg), lanes: JSON.stringify(lanes) + '\n',
    ...Object.fromEntries(Object.entries(dependencies).map(([k, v]) => [k, JSON.stringify(v, null, 2) + '\n']))};
  const writes = Object.entries(outputs).map(([k, after]) => ({...inputs[k], after: Buffer.from(after)}));
  const implementation = ['public/rail-network.js', 'scripts/railway/build-display-lanes.mjs',
    'scripts/railway/repair-three-reversal-extents.mjs', 'scripts/railway/local-evidence-path.mjs',
    'scripts/railway/repair-jr-west-etsumihoku-display.mjs'].map(p => snapshot(path.join(APP, p)));
  applyPreparedWrites(writes, [...Object.values(inputs), authority, receipt, ...implementation]);
  console.log(JSON.stringify({mode: 'applied', lineID: LINE, stationIDs: STATIONS, intervalIndices: INTERVALS,
    nativeRows: lanes.partsByRegion.jp.filter(r => r[0] === LINE).map(r => r.slice(0, 7)),
    fullPassengerCapsCertified: false, wholeLineAccepted: false, MainCertified: false}));
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main(process.argv.slice(2));
